begin;
create table public.farms(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),name text not null check(length(name) between 1 and 80),description text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index on public.farms(owner_id);
create table public.farm_zones(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id),name text not null check(length(name) between 1 and 80),description text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index on public.farm_zones(farm_id);
create table public.devices(id uuid primary key default gen_random_uuid(),farm_zone_id uuid not null references public.farm_zones(id),name text not null check(length(name) between 1 and 80),device_type text not null default 'ESP32_SHT31' check(device_type='ESP32_SHT31'),firmware_version text,last_seen_at timestamptz,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index on public.devices(farm_zone_id);
create index on public.devices(last_seen_at) where is_active;
create table public.device_credentials(id uuid primary key default gen_random_uuid(),device_id uuid not null references public.devices(id),key_hash text not null unique check(key_hash ~ '^[0-9a-f]{64}$'),revoked_at timestamptz,created_at timestamptz not null default now());
create unique index credential_active on public.device_credentials(device_id) where revoked_at is null;
create table public.sensor_readings(id bigint generated always as identity primary key,device_id uuid not null references public.devices(id),temperature numeric not null check(temperature between -40 and 125),humidity numeric not null check(humidity between 0 and 100),recorded_at timestamptz not null default now());
create index readings_device_time on public.sensor_readings(device_id,recorded_at desc);
create table public.device_thresholds(id uuid primary key default gen_random_uuid(),device_id uuid not null unique references public.devices(id),min_temperature numeric not null default 18,max_temperature numeric not null default 28,min_humidity numeric not null default 50,max_humidity numeric not null default 75,offline_after_seconds integer not null default 120 check(offline_after_seconds between 60 and 86400),updated_at timestamptz not null default now(),check(min_temperature>=-40 and max_temperature<=125 and min_temperature<max_temperature),check(min_humidity>=0 and max_humidity<=100 and min_humidity<max_humidity));
create table public.alerts(id uuid primary key default gen_random_uuid(),device_id uuid not null references public.devices(id),alert_type text not null check(alert_type in ('temperature_high','temperature_low','humidity_high','humidity_low','offline','sensor_error')),severity text not null check(severity in ('warning','danger')),message text not null,resolved_at timestamptz,acknowledged_at timestamptz,created_at timestamptz not null default now());
create unique index alert_open on public.alerts(device_id,alert_type) where resolved_at is null;
create index on public.alerts(device_id,created_at desc);
create function public.owns_zone(p_zone uuid) returns boolean language sql stable security invoker set search_path='' as $$select exists(select 1 from public.farm_zones z join public.farms f on f.id=z.farm_id where z.id=p_zone and f.owner_id=(select auth.uid()))$$;
create function public.owns_device(p_device uuid) returns boolean language sql stable security invoker set search_path='' as $$select exists(select 1 from public.devices d where d.id=p_device and public.owns_zone(d.farm_zone_id))$$;
alter table public.farms enable row level security;
alter table public.farm_zones enable row level security;
alter table public.devices enable row level security;
alter table public.device_credentials enable row level security;
alter table public.sensor_readings enable row level security;
alter table public.device_thresholds enable row level security;
alter table public.alerts enable row level security;
create policy farms_owner on public.farms for all to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy zones_owner on public.farm_zones for all to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid()))) with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy devices_owner on public.devices for all to authenticated using(public.owns_zone(farm_zone_id)) with check(public.owns_zone(farm_zone_id));
create policy thresholds_owner on public.device_thresholds for all to authenticated using(public.owns_device(device_id)) with check(public.owns_device(device_id));
create policy readings_owner on public.sensor_readings for select to authenticated using(public.owns_device(device_id));
create policy alerts_read on public.alerts for select to authenticated using(public.owns_device(device_id));
create policy alerts_ack on public.alerts for update to authenticated using(public.owns_device(device_id)) with check(public.owns_device(device_id));
revoke all on public.farms,public.farm_zones,public.devices,public.device_credentials,public.sensor_readings,public.device_thresholds,public.alerts from anon,authenticated;
grant select,insert,update on public.farms,public.farm_zones,public.device_thresholds to authenticated;
grant select on public.devices to authenticated;
grant update(name,farm_zone_id,device_type,is_active) on public.devices to authenticated;
grant select on public.sensor_readings,public.alerts to authenticated;
grant update(acknowledged_at) on public.alerts to authenticated;
grant all on all tables in schema public to service_role;
grant usage,select on all sequences in schema public to service_role;
create function public.touch_updated() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now();return new;end$$;
create trigger farms_touch before update on public.farms for each row execute function public.touch_updated();
create trigger zones_touch before update on public.farm_zones for each row execute function public.touch_updated();
create trigger devices_touch before update on public.devices for each row execute function public.touch_updated();
create trigger thresholds_touch before update on public.device_thresholds for each row execute function public.touch_updated();
-- Privileged entry point: ownership is checked before any write. Credentials are never readable by users.
create function public.register_device(p_zone uuid,p_name text,p_hash text) returns uuid language plpgsql security definer set search_path='' as $$declare v_id uuid;begin if auth.uid() is null or not public.owns_zone(p_zone) then raise exception 'forbidden';end if;insert into public.devices(farm_zone_id,name) values(p_zone,p_name) returning id into v_id;insert into public.device_thresholds(device_id) values(v_id);insert into public.device_credentials(device_id,key_hash) values(v_id,p_hash);return v_id;end$$;
revoke all on function public.register_device(uuid,text,text) from public,anon;
grant execute on function public.register_device(uuid,text,text) to authenticated;
create function public.rotate_credential(p_device uuid,p_hash text) returns void language plpgsql security invoker set search_path='' as $$begin perform 1 from public.devices where id=p_device for update;update public.device_credentials set revoked_at=now() where device_id=p_device and revoked_at is null;if p_hash is not null then insert into public.device_credentials(device_id,key_hash) values(p_device,p_hash);end if;end$$;
revoke all on function public.rotate_credential(uuid,text) from public,anon,authenticated;
grant execute on function public.rotate_credential(uuid,text) to service_role;
create function public.set_alert(p_device uuid,p_type text,p_active boolean,p_message text,p_severity text default 'warning') returns void language plpgsql security invoker set search_path='' as $$begin
if not p_active then update public.alerts set resolved_at=now() where device_id=p_device and alert_type=p_type and resolved_at is null;
elsif not exists(select 1 from public.alerts where device_id=p_device and alert_type=p_type and (resolved_at is null or created_at>now()-interval '5 minutes')) then insert into public.alerts(device_id,alert_type,severity,message) values(p_device,p_type,p_severity,p_message);end if;end$$;
revoke all on function public.set_alert(uuid,text,boolean,text,text) from public,anon,authenticated;
grant execute on function public.set_alert(uuid,text,boolean,text,text) to service_role;
create function public.ingest_reading(p_device uuid,p_hash text,p_temperature numeric,p_humidity numeric,p_firmware text,p_sensor_error boolean default false) returns jsonb language plpgsql security invoker set search_path='' as $$declare d public.devices;t public.device_thresholds;v_time timestamptz=clock_timestamp();begin
select * into d from public.devices where id=p_device for update;
if d.id is null or not d.is_active or not exists(select 1 from public.device_credentials where device_id=p_device and key_hash=p_hash and revoked_at is null) then return jsonb_build_object('status',401);end if;
if d.last_seen_at>v_time-interval '10 seconds' then return jsonb_build_object('status',429);end if;
if not p_sensor_error and (p_temperature is null or p_humidity is null or p_temperature not between -40 and 125 or p_humidity not between 0 and 100 or p_temperature::text in ('NaN','Infinity','-Infinity') or p_humidity::text in ('NaN','Infinity','-Infinity')) then raise exception 'invalid reading';end if;
if length(p_firmware)>64 then raise exception 'invalid firmware';end if;
update public.devices set last_seen_at=v_time,firmware_version=coalesce(p_firmware,firmware_version) where id=p_device;
perform public.set_alert(p_device,'offline',false,'장치 오프라인');
perform public.set_alert(p_device,'sensor_error',p_sensor_error,'센서 측정 실패','danger');
if not p_sensor_error then
insert into public.sensor_readings(device_id,temperature,humidity,recorded_at) values(p_device,p_temperature,p_humidity,v_time);
select * into t from public.device_thresholds where device_id=p_device;
perform public.set_alert(p_device,'temperature_high',p_temperature>t.max_temperature,'온도 상한 초과','danger');
perform public.set_alert(p_device,'temperature_low',p_temperature<t.min_temperature,'온도 하한 미달','danger');
perform public.set_alert(p_device,'humidity_high',p_humidity>t.max_humidity,'습도 상한 초과');
perform public.set_alert(p_device,'humidity_low',p_humidity<t.min_humidity,'습도 하한 미달');end if;
return jsonb_build_object('status',201,'recorded_at',v_time);end$$;
revoke all on function public.ingest_reading(uuid,text,numeric,numeric,text,boolean) from public,anon,authenticated;
grant execute on function public.ingest_reading(uuid,text,numeric,numeric,text,boolean) to service_role;
create function public.detect_offline() returns integer language plpgsql security invoker set search_path='' as $$declare d record;n integer=0;begin for d in select dev.id from public.devices dev join public.device_thresholds t on t.device_id=dev.id where dev.is_active and coalesce(dev.last_seen_at,dev.created_at)<now()-make_interval(secs=>t.offline_after_seconds) for update of dev loop perform public.set_alert(d.id,'offline',true,'장치 통신이 끊겼습니다.','danger');n=n+1;end loop;return n;end$$;
revoke all on function public.detect_offline() from public,anon,authenticated;
grant execute on function public.detect_offline() to service_role;
create function public.latest_readings() returns setof public.sensor_readings language sql stable security invoker set search_path='' as $$select r.* from public.devices d cross join lateral(select * from public.sensor_readings s where s.device_id=d.id order by s.recorded_at desc limit 1) r$$;
create function public.reading_history(p_device uuid,p_hours integer) returns table(recorded_at timestamptz,temperature numeric,humidity numeric,min_temperature numeric,max_temperature numeric,min_humidity numeric,max_humidity numeric,samples bigint) language sql stable security invoker set search_path='' as $$select date_bin(case when p_hours=1 then interval '1 minute' when p_hours=24 then interval '5 minutes' else interval '1 hour' end,s.recorded_at,'2000-01-01'::timestamptz),avg(s.temperature),avg(s.humidity),min(s.temperature),max(s.temperature),min(s.humidity),max(s.humidity),count(*) from public.sensor_readings s where s.device_id=p_device and p_hours in(1,24,168,720) and s.recorded_at>=now()-make_interval(hours=>p_hours) group by 1 order by 1 limit 721$$;
revoke all on function public.latest_readings(),public.reading_history(uuid,integer),public.owns_zone(uuid),public.owns_device(uuid) from public,anon;
grant execute on function public.latest_readings(),public.reading_history(uuid,integer),public.owns_zone(uuid),public.owns_device(uuid) to authenticated,service_role;
commit;
